  v8::Isolate* isolate = info.GetIsolate();
  v8::Local<v8::String> name_str = name->ToString(isolate->GetCurrentContext()).ToLocalChecked();

  // Retrieve the associated LocalDOMWindow
  LocalDOMWindow* window = GetCurrentWindow();
  if (!window)
    return;

  // Check if the window is attached to a frame
  if (!window->IsAttachedToFrame())
    return;

  // Search for sub-frames and named items in the document
  const Frame* frame = window->GetFrame();
  if (!frame)
    return;

  const Document* document = frame->GetDocument();
  if (!document)
    return;

  // Convert the v8 string to a UTF8 string for comparison
  v8::String::Utf8Value utf8_name(isolate, name_str);
  String name_string(*utf8_name);

  // Search for named items in the document
  Node* named_item = document->GetNamedItem(name_string);
  if (named_item) {
    v8::Local<v8::Value> v8_value = V8ObjectBuilder(isolate, named_item).Build();
    info.GetReturnValue().Set(v8_value);
    return;
  }

