    v8::Local<v8::Value> v8_value = V8ObjectBuilder(isolate, sub_frame->DomWindow()).Build();
    info.GetReturnValue().Set(v8_value);
    return;
  }

  // No matching item found
  info.GetReturnValue().Set(v8::Null(isolate));
